test('v19 readback fixtures bind the renderer package and retain every core package command', () => {
  const value = documents(); validateSmoothBuildDocuments(value);
  const group = engine.rustUnitGroups[20];
  assert.equal(group.label, 'readback_buffer');
  assert.equal(group.filter, 'boxhead_readback::tests::');
  assert.equal(group.expectedExecuted, 12); assert.equal(group.expectedPassed, 12);
  assert.equal(group.expectedFailed, 0); assert.equal(group.expectedIgnored, 0);
  assert.equal(group.exactNames.length, 12);
  for (let index = 0; index < EXPECTED_GROUPS; index++) {
    const command = value.plan.stages[index].command, position = command.indexOf('-p');
    assert(position > 0);
    assert.equal(command[position + 1], index === 20 ? 'ruffle_render_wgpu' : 'ruffle_core');
  }
  for (const [index, packageName] of [[20, 'ruffle_core'], [0, 'ruffle_render_wgpu'], [20, 'unreviewed_renderer']]) {
    const changed = documents();
    changeCommand(changed, index, argv => { argv[argv.indexOf('-p') + 1] = packageName; });
    assert.throws(() => validateSmoothBuildDocuments(changed), 'Consistent plan/capture cannot select another package');
  }
  for (const change of [
    changed => { changed.rustUnitGroups.pop(); },
    changed => { changed.rustUnitGroups[20].filter = 'boxhead_readback_'; },
    changed => { changed.rustUnitGroups[20].exactNames.reverse(); },
    changed => { const group = changed.rustUnitGroups[20]; group.exactNames.pop(); group.expectedExecuted--; group.expectedPassed--; },
    changed => { changed.rustUnitGroups[20].exactNames[0] = changed.rustUnitGroups[20].exactNames[1]; },
    changed => { changed.rustUnitGroups[20].exactNames[0] = 'boxhead_readback::tests::unreviewed'; },
    changed => { changed.rustUnitGroups[20].expectedIgnored = 1; changed.rustUnitGroups[20].exactIgnoredNames = ['unreviewed::ignored']; },
  ]) {
    const changed = structuredClone(engine); change(changed);
    changed.totalRequiredRustTests = changed.rustUnitGroups.reduce((sum, group) => sum + group.expectedPassed, 0);
    assert.throws(() => validateSmoothEngine(changed, parent, graphParent));
  }
  for (const change of [
    changed => { changed.plan.stages.splice(20, 1); changed.capture.stages.splice(20, 1); },
    changed => { changed.fixtures.groups[20].log = rec('inherited-renderer.log'); },
    changed => { changed.fixtures.groups[20].exactNames.pop(); changed.fixtures.groups[20].passed--; changed.fixtures.groups[20].executed--; },
    changed => { changed.fixtures.groups[20].ignored = 1; changed.fixtures.groups[20].exactIgnoredNames = ['unreviewed::ignored']; },
    changed => changeCommand(changed, 20, argv => { argv[argv.indexOf(group.filter)] = 'boxhead_readback_'; }),
  ]) {
    const changed = documents(); change(changed);
    changed.fixtures.totalExecuted = changed.fixtures.groups.reduce((sum, group) => sum + group.executed, 0);
    assert.throws(() => validateSmoothBuildDocuments(changed));
  }
  const resources = { maxRssKiB: 12345, scope: SMOOTH_RESOURCE_SCOPE }, text = rustLog(group, resources);
  for (const broken of [
    text.replace('test ' + group.exactNames[0] + ' ... ok\n', ''),
    text.replace(group.exactNames[0], 'boxhead_readback::tests::unreviewed'),
    text.replace('test ' + group.exactNames[0] + ' ... ok', 'test ' + group.exactNames[0] + ' ... ignored'),
  ]) assert.throws(() => validateSmoothRustLogs(group, broken, resources));
});

